import { Icon, type IconDefinition } from '@finalytic/icons';
import type { ExtendedCustomColors } from '@finalytic/ui/src/styles/theme';
import { Avatar, Indicator } from '@mantine/core';

type AppState =
  | 'not-active'
  | 'signing-in'
  | 'signed-in'
  | 'reconnect-not-matching'
  | 'success'
  | 'error';

const INDICATOR_COLOR: Record<AppState, ExtendedCustomColors> = {
  'not-active': 'grape',
  'signing-in': 'orange',
  'signed-in': 'purple',
  'reconnect-not-matching': 'purple',
  success: 'green',
  error: 'red',
};

const INDICATOR_ICON: Record<
  AppState,
  {
    icon: IconDefinition;
    size: number;
    strokeWidth?: number;
  }
> = {
  'not-active': {
    icon: 'ArrowRightIcon',
    size: 14,
    strokeWidth: 3,
  },
  'signing-in': {
    icon: 'ArrowCornerCcwRbIcon',
    size: 14,
    strokeWidth: 3,
  },
  'signed-in': {
    icon: 'ArrowRightIcon',
    size: 14,
    strokeWidth: 3,
  },
  'reconnect-not-matching': {
    icon: 'ArrowRightIcon',
    size: 14,
    strokeWidth: 3,
  },
  success: {
    icon: 'CheckIcon',
    size: 14,
  },
  error: {
    icon: 'CrossIcon',
    size: 14,
  },
};

type App = {
  id: string;
  name: string;
  icon: string | undefined;
};

export type ExtensionAppIconProps = {
  app: App | undefined;
  state: AppState;
};

export const ExtensionAppIcon = ({ app, state }: ExtensionAppIconProps) => {
  if (!app) return null;

  return (
    <Indicator
      position="bottom-end"
      color={INDICATOR_COLOR[state] || 'grape'}
      label={
        <Icon
          icon={INDICATOR_ICON[state].icon || 'ArrowRightIcon'}
          size={INDICATOR_ICON[state].size ?? 14}
          strokeWidth={INDICATOR_ICON[state].strokeWidth}
          color={(theme) => theme.white}
        />
      }
      styles={() => ({
        indicator: {
          height: 24,
          width: 24,
          right: 0,
          bottom: 11,
          border: '2px solid white',
        },
      })}
    >
      <Avatar src={app.icon} alt={app.name || 'App'} size={45}>
        {app.name?.slice(0, 1).toUpperCase()}
      </Avatar>
    </Indicator>
  );
};
