import { useQuery } from '@finalytic/data';
import { getIntegrationsDisplayName } from '../../background/integrations';
import { useAuthContext } from '../hooks/useAuthContext';
import { useExtensionContext } from '../hooks/useExtensionContext';
import { ExtensionAddView } from '../views/ExtensionAddView';

function useApps() {
  const { teamId } = useAuthContext();

  const { data: apps, isLoading: loading } = useQuery(
    (q, args) => {
      const apps = q
        .app({ where: { id: { _in: args.appIds } } })
        .map((app) => ({
          id: app.id,
          name: app.name,
          icon: app.iconRound,
          activeConnections: args.teamId
            ? app
                .connections_aggregate({
                  where: {
                    tenantId: { _eq: args.teamId },
                    status: { _eq: 'active' },
                  },
                })
                .aggregate?.count()
            : undefined,
        }));

      return apps;
    },
    {
      variables: {
        appIds: getIntegrationsDisplayName,
        teamId,
      },
    }
  );

  return {
    apps: apps || [],
    loading,
  };
}

export const Add = () => {
  const { setView, setAppId, resetView } = useExtensionContext();

  const { apps } = useApps();

  const submitRow = (appId: string) => {
    setAppId(appId);
    setView('connect-view');
  };

  return (
    <ExtensionAddView
      apps={apps as any[]}
      onRowSubmit={submitRow}
      onReturn={resetView}
    />
  );
};
