import { Icon } from '@finalytic/icons';
import {
  Avatar,
  Box,
  Center,
  Stack,
  Text,
  useMantineTheme,
} from '@mantine/core';
import { ExtensionViewHeader } from '../components';

type App = {
  id: string;
  name: string;
  icon: string | null;
  url?: string;
};

type RowSubmitHandler = (appId: string) => void;

type ExtensionAddViewProps = {
  onReturn: () => void;
  onRowSubmit: RowSubmitHandler;
  apps: App[];
};

export const ExtensionAddView = ({
  onReturn,
  apps,
  onRowSubmit,
}: ExtensionAddViewProps) => {
  const theme = useMantineTheme();

  return (
    <>
      <ExtensionViewHeader title="Add new connection" onReturn={onReturn} />

      <Box
        sx={{
          display: 'flex',
          flex: 0.8,
          flexDirection: 'column',
          marginInline: 'auto',
          justifyContent: 'center',
        }}
      >
        <Stack w={350} mb="xl">
          {apps
            .sort((a, b) => a.name.localeCompare(b.name))
            .map((i) => (
              <Row onRowSubmit={onRowSubmit} key={i.id} {...i} />
            ))}
        </Stack>
        <Text fw={500} c={theme.colors.neutral[4]} size="sm" ta="center">
          Select an app to link with VRPlatform.
        </Text>
      </Box>
    </>
  );
};

type RowProps = {
  onRowSubmit: RowSubmitHandler;
};
const Row = ({ id, name, icon, onRowSubmit }: App & RowProps) => {
  const theme = useMantineTheme();

  return (
    <Box
      component="button"
      sx={(theme) => ({
        display: 'flex',
        flexWrap: 'nowrap',
        alignItems: 'center',
        justifyContent: 'flex-start',
        gap: theme.spacing.md,
        backgroundColor: theme.white,
        padding: theme.spacing.md,
        border: `1px solid ${theme.colors.neutral[2]}`,
        boxShadow: theme.shadows.sm,
        borderRadius: theme.radius.md,
        cursor: 'pointer',
        transition: 'all 0.1s ease-in-out',
        '&:hover': {
          boxShadow: theme.shadows.md,
        },
      })}
      onClick={() => onRowSubmit(id)}
    >
      <Avatar src={icon} alt={name} size={32}>
        {name?.slice(0, 1).toUpperCase()}
      </Avatar>
      <Text c={theme.colors.neutral[5]} fw={500} size={'md'}>
        Login to{' '}
        <Text span inherit c={theme.colors.neutral[8]}>
          {name}
        </Text>
      </Text>
      <Center ml="auto">
        <Icon
          icon="ArrowTopRightRecIcon"
          size={20}
          color={(theme) => theme.colors.neutral[3]}
        />
      </Center>
    </Box>
  );
};
