import { Center, Text } from '@mantine/core';
import { ExtensionViewHeader } from '../components';
import { useExtensionContext } from '../hooks/useExtensionContext';
import { Action, ExtensionConnectView } from '../views/ExtensionConnectView';
import { ExtensionPayoutResultView } from '../views/ExtensionPayoutResultView';

export const PayoutResult = () => {
  const { app, resetView } = useExtensionContext();

  if (!app)
    return (
      <ExtensionConnectView
        app={app}
        header="Failed to connect"
        loading
        state="signing-in"
        onReturn={resetView}
      />
    );

  return <ExtensionPayoutResultView app={app} onReturn={resetView} />;
};

export const PayoutExtraction = (props: {
  total: number;
  progress: number;
  message: string;
}) => {
  const { app, resetView } = useExtensionContext();

  return (
    <>
      <ExtensionViewHeader title={'Success!'} onReturn={resetView} />
      <Center
        sx={{
          height: '100%',
          flexDirection: 'column',
          flex: '1',
        }}
      >
        <Action
          app={app!}
          state={'success'}
          title={props.message}
          description={`${props.progress} / ${props.total}`}
          secondary={{
            label: 'Return to overview',
            onClick: resetView,
          }}
        />

        <br />
        <Text>Please do not close the page or refresh the page.</Text>
      </Center>
    </>
  );
};
