import type { CustomThemes } from '@finalytic/ui';
import { useMantineTheme } from '@mantine/core';
import { useEffect } from 'react';
import {
  type ReactNode,
  createContext,
  useContext,
  useMemo,
  useState,
} from 'react';
import { setPlatformTeamId } from './localStorage';

type context = {
  // Loading Token
  token: string | undefined;
  loading: boolean;
  error: string | undefined;

  // Active User & Team
  userId: string | undefined;
  teamId: string | undefined;
  setTeamId: (teamId: string) => void;
};

const AuthContext = createContext<context | null>(null);

export type AuthContextProviderProps = {
  children?: ReactNode;
};

export const useAuthContext = () => useContext(AuthContext) as context;

// AccessToken helpers
function isTokenExpired(token?: string) {
  if (!token) return true;
  const expiry = JSON.parse(atob(token.split('.')[1])).exp;
  // biome-ignore lint/complexity/useDateNow: <explanation>
  return Math.floor(new Date().getTime() / 1000) >= expiry;
}

export const AuthContextProvider = ({ children }: AuthContextProviderProps) => {
  const [token, setToken] = useState<string>();
  const [loading, setLoading] = useState(true);
  const [userId, setUserId] = useState<string>();
  const [teamId, setTeamId] = useState<string>();

  const { primaryColor: platform } = useMantineTheme();

  useEffect(() => {
    const listener = (changes: {
      [key: string]: chrome.storage.StorageChange;
    }) => {
      if ('accessToken' in changes) {
        if (!isTokenExpired(changes.accessToken.newValue)) {
          setToken(changes.accessToken.newValue);
        }
      }
      if ('userId' in changes) setUserId(changes.userId.newValue);
      if ('teamId' in changes) setTeamId(changes.teamId.newValue);
    };

    const getInitial = async () => {
      await chrome.storage.local.get().then(async (state) => {
        listener({
          accessToken: { newValue: state.accessToken },
          userId: { newValue: state.userId },
          teamId: { newValue: state.teamId },
        });
        setLoading(false);
      });
    };
    getInitial();

    chrome.storage.onChanged.addListener(listener);

    return () => chrome.storage.onChanged.removeListener(listener);
  }, []);

  const value = useMemo(
    () => ({
      token,
      loading,
      error: undefined,
      userId,
      teamId,
      setTeamId: async (teamId: string) => {
        chrome.storage.local.set({ teamId });
        setPlatformTeamId({
          teamId,
          platform: platform as CustomThemes,
          userId: userId!,
        });
      },
    }),
    [token, loading, userId, teamId, platform]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};
