import { useExtensionContext } from '../hooks/useExtensionContext';
import { ExtensionConnectView } from '../views/ExtensionConnectView';
import { ExtensionResultView } from '../views/ExtensionResultView';

export const Result = () => {
  const { resetView, app, errorMessage } = useExtensionContext();

  if (!app)
    return (
      <ExtensionConnectView
        app={app}
        header="Failed to connect"
        loading
        state="signing-in"
        onReturn={resetView}
      />
    );

  return (
    <ExtensionResultView app={app} error={errorMessage} onReturn={resetView} />
  );
};
