import type { CustomThemes } from '@finalytic/ui';
import { evaluateOnTab } from '../../background/utils';

const urlMatcher: { [_key in CustomThemes]: string } = {
  finalytic: 'https://*.finalytic.io/*',
  vrplatform: 'https://*.vrplatform.app/*',
};

export const setPlatformTeamId = async ({
  platform,
  teamId,
  userId,
}: {
  teamId: string;
  userId: string;
  platform: CustomThemes;
}) => {
  try {
    const platformTab = await chrome.tabs.query({
      url: urlMatcher[platform],
    });

    const tabId = platformTab[0]?.id;

    if (tabId && teamId) {
      await evaluateOnTab(
        tabId,
        ({ teamId: tid, userId: uid }) => {
          localStorage.setItem(`${uid}_tid`, tid);
          localStorage.setItem('tid', tid);
        },
        [{ teamId, userId }]
      );
    }
  } catch (error) {
    console.log(error);
  }
};

