import { Filter } from '@finalytic/components';
import {
  type api,
  type gqlV2,
  useInfiniteQuery,
  useQuery,
} from '@finalytic/data';
import { Icon } from '@finalytic/icons';
import type { MRT_SortingState } from '@finalytic/table';
import type { SelectItem } from '@finalytic/ui';
import { type Maybe, ensure, toTitleCase } from '@vrplatform/utils';
import { Center } from '@mantine/core';
import { useSetState } from '@mantine/hooks';
import { useEffect, useMemo, useState } from 'react';
import { getIntegrationsDisplayName } from '../../background/integrations';
import { useAuthContext } from '../hooks/useAuthContext';
import {
  type ExtensionConnectionFilter,
  useExtensionConnectionsTableQuery,
} from '../hooks/useExtensionConnectionsTableQuery';
import { useExtensionContext } from '../hooks/useExtensionContext';
import { ExtensionListView } from '../views/ExtensionListView';

export const List = () => {
  const { setView, setConnectionId } = useExtensionContext();
  const { setTeamId, teamId: authTeamId } = useAuthContext();

  const initialFilter: ExtensionConnectionFilter = {
    search: undefined,
    appId: undefined,
    status: undefined,
  };
  const [filter, setFilter] =
    useSetState<ExtensionConnectionFilter>(initialFilter);

  const [sorting, setSorting] = useState<MRT_SortingState>([
    { id: 'name', desc: false },
  ]);

  const { data: team, isLoading: loadingTeam } = useQuery(
    (q, args) => {
      if (!args.authTeamId) return null;

      return (
        q
          .tenant({
            where: {
              id: { _eq: args.authTeamId },
            },
          })
          .map((x) => ({
            id: x.id,
            name: x.name,
          }))[0] || null
      );
    },
    {
      skip: !authTeamId,
      variables: {
        authTeamId,
      },
    }
  );

  const queryTeamId = team?.id;

  useEffect(() => {
    if (!authTeamId && queryTeamId) setTeamId(queryTeamId);
  }, [authTeamId, queryTeamId, setTeamId]);

  const queryData = useExtensionConnectionsTableQuery({ sorting, filter });

  return (
    <ExtensionListView
      loadingTeam={loadingTeam}
      teamName={team?.name}
      currentTeamId={queryTeamId}
      filter={filter}
      setFilter={setFilter}
      sorting={sorting}
      setSorting={setSorting}
      goToAddView={() => {
        setConnectionId('');
        setView('add-view');
      }}
      onSelectRow={(connectionId) => {
        setConnectionId(connectionId);
        setView('connect-view');
      }}
      queryData={queryData}
    >
      <AppFilter
        value={filter.appId}
        setValue={(value) => setFilter({ appId: value })}
      />
      <FetchStatusFilter
        value={filter.status}
        setValue={(value) => setFilter({ status: value })}
      />
    </ExtensionListView>
  );
};

const AppFilter = ({
  setValue,
  value,
}: {
  value: Maybe<string>;
  setValue: (value: Maybe<string>) => void;
}) => {
  const { teamId } = useAuthContext();

  const [search, setSearch] = useState('');

  const queryData = useInfiniteQuery(
    (q, { teamId, search }, { limit, offset }) => {
      const where: gqlV2.connection_bool_exp = {
        tenantId: { _eq: teamId },
        appId: {
          _is_null: false,
          _neq: 'finalytic',
          _in: getIntegrationsDisplayName,
        },
        _or: search
          ? [
              {
                appId: { _ilike: `%${search}%` },
              },
              {
                app: { name: { _ilike: `%${search}%` } },
              },
            ]
          : undefined,
      };

      const list = q
        .connection({
          where,
          order_by: [{ appId: 'asc' }],
          limit,
          offset,
          distinct_on: ['appId'],
        })
        .map<SelectItem>((res) => ({
          value: res.appId!,
          label: res.app.name!,
        }));

      const aggregate =
        q
          .connectionAggregate({ where, distinct_on: ['appId'] })
          .aggregate?.count() || 0;

      return {
        list,
        aggregate,
      };
    },
    {
      skip: !teamId,
      queryKey: ['connections'],
      variables: {
        teamId,
        search: search?.trim(),
      },
    }
  );

  const { data } = useQuery(
    (q, { appId }) => {
      const value = q
        .app({ where: { id: { _eq: appId } }, limit: 1 })
        .map<SelectItem>((item) => ({
          label: item.name || '',
          value: item.id!,
        }))?.[0];

      return {
        value,
      };
    },
    {
      skip: !teamId,
      queryKey: ['connections'],
      variables: {
        appId: value,
      },
    }
  );

  const selectValue = value ? data?.value || null : null;

  return (
    <Filter.Select
      value={selectValue}
      setValue={(v) => setValue(v?.value)}
      label="App"
      type="single"
      withinPortal
      infiniteData={{ ...queryData, setSearch }}
    />
  );
};

type ConnectionSyncStatus = NonNullable<
  NonNullable<
    api['/connections']['get']['parameters']['query']
  >['currentSyncStatus']
>;

const FetchStatusFilter = ({
  setValue,
  value,
}: {
  value: Maybe<string>;
  setValue: (value: Maybe<string>) => void;
}) => {
  const options = useMemo<SelectItem<ConnectionSyncStatus>[]>(
    () => [
      {
        label: 'Active',
        value: 'completed',
        icon: (
          <Center
            sx={(theme) => ({
              backgroundColor: `${theme.colors.green[5]}30`,
              width: 15,
              height: 15,
              borderRadius: '50%',
              alignSelf: 'center',
            })}
          >
            <Icon
              size={12}
              icon={'CheckIcon'}
              color={(theme) => theme.colors.green[7]}
            />
          </Center>
        ),
      },
      {
        label: 'Error',
        value: 'failed',
        icon: (
          <Center
            sx={(theme) => ({
              backgroundColor: `${theme.colors.red[5]}30`,
              width: 15,
              height: 15,
              borderRadius: '50%',
              alignSelf: 'center',
            })}
          >
            <Icon
              size={12}
              icon={'CrossIcon'}
              color={(theme) => theme.colors.red[7]}
            />
          </Center>
        ),
      },
    ],
    []
  );

  const selectValue = value
    ? ensure<SelectItem>({
        value: value,
        label: toTitleCase(value)!,
      })
    : null;

  return (
    <Filter.Select
      value={selectValue}
      setValue={(v) => setValue(v?.value)}
      label="Status"
      type="single"
      withinPortal
      // infiniteData={{ ...queryData, setSearch }}
      data={{
        options,
      }}
    />
  );
};
