import { IconButton } from '@finalytic/components';
import { Logo } from '@finalytic/ui';
import {
  Center,
  Group,
  Space,
  Text,
  rem,
  useMantineTheme,
} from '@mantine/core';
import type { ReactNode } from 'react';

type Props = {
  children?: ReactNode;
  title: string;
  withLogo?: boolean;
  onReturn?: () => void;
};
export const ExtensionViewHeader = ({
  children,
  title,
  // withLogo = true,
  onReturn,
}: Props) => {
  const theme = useMantineTheme();

  return (
    <Group
      gap={0}
      justify="space-between"
      align="center"
      h={rem(48)}
      sx={(theme) => ({
        backgroundColor: theme.colors.neutral[0],
        borderBottom: `1px solid ${theme.colors.neutral[1]}`,
        paddingBlock: rem(8),
        paddingInline: rem(8),
      })}
    >
      {onReturn ? (
        <Center>
          <IconButton icon="ArrowLeftIcon" iconSize={22} onClick={onReturn} />
        </Center>
      ) : (
        <Logo background="transparent" />
      )}
      <Text fw={500} size={rem(16)} c={theme.colors.neutral[6]}>
        {title}
      </Text>
      {children || <Space w={45} />}
    </Group>
  );
};
