import { Center } from '@mantine/core';
import { type ExtensionAppIconProps, ExtensionViewHeader } from '../components';
import { Action } from './ExtensionConnectView';

export const ExtensionResultView = ({
  onReturn,
  error,
  app,
}: {
  onReturn: () => void;
  error?: string;
  app: NonNullable<ExtensionAppIconProps['app']>;
}) => {
  return (
    <>
      <ExtensionViewHeader
        title={error ? 'Error!' : 'Success!'}
        onReturn={onReturn}
      />
      <Center
        sx={{
          height: '100%',
          flexDirection: 'column',
          flex: '1',
        }}
      >
        <Action
          app={app}
          description={
            error || 'Your account is now successfully linked to VRPlatform.'
          }
          title={!error && app ? `${app.name} connected!` : 'Failed to connect'}
          state={error ? 'error' : 'success'}
          secondary={{
            label: 'Return to overview',
            onClick: onReturn,
          }}
        />
      </Center>
    </>
  );
};
