import { type api, useApiClient } from '@finalytic/data';
import type { MRT_SortingState } from '@finalytic/table';
import type { Maybe } from '@vrplatform/utils';
import {
  keepPreviousData,
  useInfiniteQuery as useTanstackInfiniteQuery,
} from '@tanstack/react-query';
import { getIntegrationsDisplayName } from '../../background/integrations';
import { useAuthContext } from './useAuthContext';

export type ExtensionConnectionFilter = {
  search: Maybe<string>;
  appId: Maybe<string>;
  status: Maybe<string>;
};

export type ExtensionConnectionRow = NonNullable<
  ReturnType<typeof useExtensionConnectionsTableQuery>['data']
>['pages'][number]['list'][number];

const getConnectionGetParams = (
  filter: ExtensionConnectionFilter
): NonNullable<api['/connections']['get']['parameters']['query']> => {
  return {
    appId: filter.appId ?? getIntegrationsDisplayName.join(','),
    status: 'active',
    search: filter.search?.trim() || undefined,
    currentSyncStatus: (() => {
      const st = (filter.status ?? undefined)?.toLowerCase();

      type SyncStatus = NonNullable<
        NonNullable<
          api['/connections']['get']['parameters']['query']
        >['currentSyncStatus']
      >;

      const status = {
        completed: 'completed',
        // issues: 'issues',
        failed: 'failed',
        queued: 'queued',
        started: 'started',
        canceled: 'canceled',
      } satisfies Record<SyncStatus, SyncStatus>;

      return status[(st as keyof typeof status) || ''] ?? undefined;
    })(),
  };
};

export function useExtensionConnectionsTableQuery({
  sorting,
  filter,
}: {
  sorting: MRT_SortingState;
  filter: ExtensionConnectionFilter;
}) {
  const { teamId } = useAuthContext();
  const $api = useApiClient();

  const trimmed = filter.search?.trim() || undefined;

  return useTanstackInfiniteQuery({
    initialPageParam: 1,
    refetchOnWindowFocus: true,
    enabled: !!teamId,
    getNextPageParam: (lastPage: any) => {
      if (lastPage?.pagination) {
        return lastPage.pagination?.nextPage;
      }

      return null; // return null if no more pages
    },
    placeholderData: keepPreviousData,
    queryKey: [
      'connections',
      sorting,
      filter.appId,
      trimmed,
      filter.status,
      teamId,
    ],
    queryFn: async ({ pageParam }) => {
      const res = await $api.GET('/connections', {
        params: {
          query: {
            ...getConnectionGetParams(filter),
            page: pageParam ?? 1,
            limit: 30,
          },
        },
      });

      if (res.error) throw res.error;

      return {
        list: res.data.data.map((c) => ({ ...c, tenantId: teamId })),
        aggregate: res.data.pagination.total ?? 0,
        pagination: res.data.pagination,
      };
    },
  });
}
