import { Button, Filter, IconButton } from '@finalytic/components';
import { Icon, type IconDefinition } from '@finalytic/icons';
import {
  InfiniteTable,
  type MRT_ColumnDef,
  type MRT_SortingState,
} from '@finalytic/table';
import {
  Avatar,
  Box,
  Center,
  Group,
  Text,
  Tooltip,
  rem,
  useMantineTheme,
} from '@mantine/core';
import { type ReactNode, useMemo } from 'react';
import { ExtensionViewHeader } from '../components';
import type {
  ExtensionConnectionFilter,
  ExtensionConnectionRow,
  useExtensionConnectionsTableQuery,
} from '../hooks/useExtensionConnectionsTableQuery';

type Props = {
  loadingTeam: boolean;
  currentTeamId: string | undefined;
  teamName: string | undefined;
  goToAddView: () => void;
  onSelectRow: (connectionId: string) => void;
  children: ReactNode;
  queryData: ReturnType<typeof useExtensionConnectionsTableQuery>;
  filter: ExtensionConnectionFilter;
  setFilter: (filter: Partial<ExtensionConnectionFilter>) => void;
  sorting: MRT_SortingState;
  setSorting: React.Dispatch<React.SetStateAction<MRT_SortingState>>;
};

export const ExtensionListView = (props: Props) => {
  return (
    <>
      <ExtensionViewHeader
        title={
          props.loadingTeam
            ? ''
            : props.teamName || 'Your VRPlatform connections'
        }
      >
        <Group gap={5} wrap="nowrap">
          {!props.loadingTeam && (
            <IconButton
              icon="RefreshCwIcon"
              onClick={() => props.queryData.refetch()}
              iconSize={16}
            />
          )}

          <IconButton
            icon="PlusIcon"
            loading={props.loadingTeam}
            disabled={!props.currentTeamId}
            onClick={props.goToAddView}
            iconSize={20}
          />
        </Group>
      </ExtensionViewHeader>

      <Table {...props} />
    </>
  );
};

const Table = ({
  onSelectRow,
  queryData,
  children,
  loadingTeam,
  filter,
  setFilter,
  sorting,
  setSorting,
  goToAddView,
}: Props) => {
  const theme = useMantineTheme();

  const trimmedSearch = filter.search?.trim();

  const columns = useMemo<MRT_ColumnDef<ExtensionConnectionRow>[]>(
    () => [
      {
        accessorKey: 'name',
        enableSorting: true,
        header: 'Connection',
        maxSize: 120,
        Cell: ({ row }) => {
          const data = row.original;
          return (
            <Group wrap="nowrap" gap="sm">
              <Avatar
                src={data.app.icon}
                size="sm"
                styles={{
                  placeholder: { visibility: 'hidden' },
                }}
              />
              <Box>
                <Text
                  size="sm"
                  component="p"
                  fw={500}
                  sx={{
                    wordBreak: 'break-all',
                  }}
                  m={0}
                >
                  {data.name}
                </Text>
                <Text
                  size="xs"
                  component="p"
                  c="neutral"
                  sx={{
                    wordBreak: 'break-all',
                  }}
                  m={0}
                >
                  {row.original.uniqueRef}
                </Text>
              </Box>
            </Group>
          );
        },
      },
      {
        header: 'Status',
        size: 30,
        mantineTableBodyCellProps: { align: 'right' },
        mantineTableHeadCellProps: { align: 'right' },
        Cell: ({ row }) => {
          const data = row.original;

          const syncStatus = data?.currentSync?.status;
          let tooltipLabel = '';

          let color: 'green' | 'yellow' | 'red' | 'orange' = 'green';
          let icon: IconDefinition = 'CheckIcon';

          if (syncStatus === 'failed' || data.isErrorState) {
            color = 'red';
            icon = 'CrossIcon';
          } else if (syncStatus === 'queued' || syncStatus === 'started') {
            color = 'yellow';
            icon = 'RefreshCwIcon';
          }

          if (data.status === 'inactive') {
            tooltipLabel = 'Archived';
            color = 'yellow';
            icon = 'ArchiveIcon';
          }

          if (!syncStatus) return null;

          return (
            <Tooltip
              label={tooltipLabel}
              disabled={!tooltipLabel}
              withArrow
              withinPortal
              maw={300}
              multiline
            >
              <Avatar size="sm" radius="xl" color={color}>
                <Icon
                  size={14}
                  icon={icon}
                  color={(theme) => theme.colors[color][7]}
                />
              </Avatar>
            </Tooltip>
          );
        },
      },
    ],
    []
  );

  const noActiveFilter = useMemo(() => {
    return !trimmedSearch && !filter.appId && !filter.status;
  }, [trimmedSearch, filter.appId, filter.status]);

  const showEmptyState = useMemo(() => {
    return queryData.data?.pages[0].list.length === 0 && noActiveFilter;
  }, [queryData.data?.pages, noActiveFilter]);

  if (showEmptyState && !queryData.error) {
    return (
      <Center
        sx={{
          display: 'flex',
          flexDirection: 'column',
          flex: 0.9,
        }}
      >
        <Center mb="xl">
          <Icon
            icon="ShareIcon"
            color={(theme) => theme.colors[theme.primaryColor][7]}
            size={32}
          />
        </Center>
        <Text
          ta="center"
          fw={600}
          mb="sm"
          size="xl"
          c={theme.colors.neutral[7]}
        >
          Connect your accounts
        </Text>
        <Text ta="center" c="neutral" mb="xl" mx="auto" maw={400}>
          No connections yet.
          <br />
          Add your first one to get started.
        </Text>
        <Button variant="primary" leftIcon="PlusIcon" onClick={goToAddView}>
          Add connection
        </Button>
      </Center>
    );
  }

  return (
    <Box
      sx={{
        display: 'flex',
        flexDirection: 'column',
        marginInline: rem(8),
        marginTop: rem(8),
        gap: rem(5),
        flex: 1,
      }}
    >
      <Group gap={5}>
        <Filter.Search
          value={filter.search || ''}
          setValue={(value) => setFilter({ search: value })}
        />

        {children}
      </Group>
      <InfiniteTable
        columns={columns}
        queryData={{
          ...queryData,
          isFetching: loadingTeam || queryData.isFetching,
        }}
        table={{
          emptyRowsFallback: 'No connections found',
          hideTopBar: true,
          onRowClick: {
            handler: (row) => onSelectRow(row.original.id),
          },
        }}
        sorting={{
          setSorting,
          sorting,
        }}
      />
    </Box>
  );
};
