import { Button } from '@finalytic/components';
import {
  ApiClientProvider,
  ExtensionGtqyProvider,
  ExtensionTrpcProvider,
  TanstackQueryClient,
  TanstackQueryClientProvider,
} from '@finalytic/data';
import {
  type CustomThemes,
  LoadingIndicator,
  RootThemeProvider,
  V2Provider,
} from '@finalytic/ui';
import { Center } from '@mantine/core';
import { Text } from '@mantine/core';
import { type ReactNode, useCallback } from 'react';
import { ExtensionViewContainer } from './components';
import { AuthContextProvider, useAuthContext } from './hooks/useAuthContext';
import { Root } from './routes/Root';
import { ExtensionLoginView } from './views/ExtensionLoginView';

const queryClient = new TanstackQueryClient();

export default function Popup() {
  const themes: { [key: string]: CustomThemes } = {
    jkcopfjpdildkbilmhcaegojcjnedmof: 'finalytic',
    dgnfieblfdbmehilhfkgepgigedgaklg: 'vrplatform',
  };

  const currentTheme = themes[chrome.runtime.id] || 'vrplatform';

  return (
    <V2Provider>
      <RootThemeProvider themePrimaryColor={currentTheme} colorScheme="light">
        <AuthContextProvider>
          <App theme={currentTheme} />
        </AuthContextProvider>
      </RootThemeProvider>
    </V2Provider>
  );
}

function App({ theme }: { theme: CustomThemes }) {
  const { error, loading, token, teamId } = useAuthContext();

  if (theme === 'finalytic') return <FinalyticMigrationView />;

  return (
    <>
      {(loading || error) && (
        <ExtensionViewContainer>
          <Center sx={{ flex: '1 1 0' }}>
            {error && <p>{error}</p>}
            {loading && <LoadingIndicator />}
          </Center>
        </ExtensionViewContainer>
      )}

      {!loading &&
        !error &&
        (!token ? (
          <ExtensionViewContainer width={400} height={400}>
            <ExtensionLoginView />
          </ExtensionViewContainer>
        ) : (
          <ExtensionTrpcProvider queryClient={queryClient} token={token}>
            <TanstackQueryClientProvider client={queryClient}>
              <ExtensionGtqyProvider token={token}>
                <ApiProvider token={token} teamId={teamId}>
                  <Root />
                </ApiProvider>
              </ExtensionGtqyProvider>
            </TanstackQueryClientProvider>
          </ExtensionTrpcProvider>
        ))}
    </>
  );
}

const ApiProvider = ({
  children,
  token,
  teamId,
}: {
  children: ReactNode;
  token: string;
  teamId: string | undefined;
}) => {
  const getToken = useCallback(async () => token, [token]);

  if (!teamId) return children;

  return (
    <ApiClientProvider getToken={getToken} teamId={teamId}>
      {children}
    </ApiClientProvider>
  );
};

const FinalyticMigrationView = () => (
  <Center
    px={5}
    my="lg"
    sx={{
      height: '100%',
      minHeight: 300,
      flexDirection: 'column',
      textAlign: 'center',
    }}
  >
    <Icons />
    <Text style={{ fontSize: 24, fontWeight: 'bold' }} my="md">
      Finalytic is now VRPlatform
    </Text>
    <Text size="sm" mb="lg" px="sm">
      Finalytic has now moved to VRPlatform. Please install the VRPlatform
      extension and remove the Finalytic extension.
    </Text>
    <Button
      component={'a'}
      variant="primary"
      href={
        'https://chromewebstore.google.com/detail/vrplatform-connect/hphpodppjfegboiaddkpkceedjjjjjma'
      }
      sx={(theme) => ({ marginBottom: theme.spacing.sm })}
      rightIcon="ExternalLinkIcon"
      target="_blank"
      rel="noopener,noreferrer"
    >
      Take me there
    </Button>
    <Button
      variant="transparent"
      size="xs"
      color="neutral"
      component="a"
      href="mailto:help@vrplatform.app"
    >
      Contact support
    </Button>
  </Center>
);

