import { ExtensionViewContainer } from '../components';
import { useAuthContext } from '../hooks/useAuthContext';
import {
  ExtensionContextProvider,
  useExtensionContext,
} from '../hooks/useExtensionContext';
import { Add } from './Add';
import { Connect } from './Connect';
import { List } from './List';
import { PayoutResult } from './PayoutResult';
import { Result } from './Result';

const ActiveView = () => {
  const { teamId } = useAuthContext();
  const { view } = useExtensionContext();

  const children = () => {
    if (!teamId) return <List />;

    switch (view) {
      case 'list-view':
        return <List />;
      case 'add-view':
        return <Add />;
      case 'connect-view':
        return <Connect />;
      case 'error-view':
      case 'success-view':
        return <Result />;
      case 'payout-success-view':
        return <PayoutResult />;
      default:
        return <List />;
    }
  };

  return <ExtensionViewContainer>{children()}</ExtensionViewContainer>;
};

export const Root = () => {
  return (
    <ExtensionContextProvider>
      <ActiveView />
    </ExtensionContextProvider>
  );
};
