import { Button } from '@finalytic/components';
import {
  useApiMutation,
  useQuery,
  useTrpcMutation,
  ApiClientError,
  getApiErrorMessage,
} from '@finalytic/data';
import { Text, rem } from '@mantine/core';
import { type ComponentProps, useEffect, useState } from 'react';
import { getIntegration } from '../../background/integrations';
import { clearSession, getSession } from '../../background/services';
import {
  type Account,
  type Integration,
  type Session,
  Status,
} from '../../background/types';
import { useAuthContext } from '../hooks/useAuthContext';
import { useExtensionContext } from '../hooks/useExtensionContext';
import { ExtensionConnectView } from '../views/ExtensionConnectView';
import { PayoutExtraction } from './PayoutResult';

export const Connect = () => {
  const { resetView, app, appLoading, connectionId } = useExtensionContext();

  const [integration, setIntegration] = useState<string>();
  const [account, setAccount] = useState<Account>();
  const [status, setStatus] = useState<string>();
  const [tabId, setTabId] = useState<number>();

  useEffect(() => {
    const listener = (store: { [s: string]: chrome.storage.StorageChange }) => {
      if ('status' in store) setStatus(store.status.newValue);
      if ('integration' in store) setIntegration(store.integration.newValue);
      if ('account' in store) setAccount(store.account.newValue);
      if ('tabId' in store) setTabId(store.tabId.newValue);
    };
    chrome.storage.onChanged.addListener(listener);
    chrome.storage.local.get().then((state) => {
      listener({
        status: { newValue: state.status },
        account: { newValue: state.account },
        tabId: { newValue: state.tabId },
        integration: { newValue: state.integration },
      });
    });

    return () => chrome.storage.onChanged.removeListener(listener);
  }, []);

  const baseProps = useBaseProps();

  if (!app) return <ExtensionConnectView {...baseProps} />;

  if (status === Status.NOT_ACTIVE || app.id !== integration) {
    return <NotActive />;
  }

  if (status === Status.SIGNING_IN) {
    return <ExtensionConnectView {...baseProps} state="signing-in" />;
  }

  if (status === Status.SIGNED_IN && integration && tabId && account) {
    return (
      <SignedIn integrationId={integration} tabId={tabId} account={account} />
    );
  }

  return (
    <ExtensionConnectView
      loading={appLoading}
      header={connectionId ? 'Reconnect Connection' : 'Add New Connection'}
      app={app}
      onReturn={resetView}
      state="not-active"
      secondaryOnClick={() => {}}
    >
      {(() => {
        if (!app) {
          return <></>;
        } else if (status === Status.NOT_ACTIVE || app.id !== integration) {
          return <NotActive />;
        } else if (status === Status.SIGNING_IN) {
          return <SigningIn integrationId={integration} />;
        } else if (
          status === Status.SIGNED_IN &&
          integration &&
          tabId &&
          account
        ) {
          return (
            <SignedIn
              integrationId={integration}
              tabId={tabId}
              account={account}
            />
          );
        }

        return <NotSignedIn status={status} integrationId={integration} />;
      })()}
    </ExtensionConnectView>
  );
};

function useBaseProps() {
  const { app, connectionId, appLoading, resetView } = useExtensionContext();

  return {
    loading: appLoading,
    onReturn: resetView,
    secondaryOnClick: () => {},
    header: connectionId ? 'Reconnect Connection' : 'Add New Connection',
    app,
    state: 'not-active',
  } satisfies ComponentProps<typeof ExtensionConnectView>;
}

const NotActive = () => {
  const { app } = useExtensionContext();

  const baseProps = useBaseProps();

  return (
    <ExtensionConnectView
      {...baseProps}
      state="not-active"
      secondaryOnClick={() => {
        window.open(app?.url, '_blank', 'noopener,noreferrer');
      }}
    />
  );
};

const NotSignedIn = ({
  status,
  integrationId,
}: {
  status: string | undefined;
  integrationId: string | undefined;
}) => {
  const { app } = useExtensionContext();
  const integration = integrationId ? getIntegration(integrationId) : undefined;
  const baseProps = useBaseProps();

  return (
    <ExtensionConnectView
      {...baseProps}
      state="not-active"
      needsRelogin={integration?.needSigning && status === Status.SIGNED_IN}
      secondaryOnClick={() => {
        window.open(app?.url, '_blank', 'noopener,noreferrer');
      }}
    />
  );
};

const SigningIn = ({
  integrationId,
}: {
  integrationId: string | undefined;
}) => {
  const integration = integrationId ? getIntegration(integrationId) : undefined;
  console.log(integration);

  const baseProps = useBaseProps();

  return <ExtensionConnectView {...baseProps} state="signing-in" />;
};

const SignedIn = ({
  account,
  tabId,
  integrationId,
}: {
  account: Account;
  tabId: number;
  integrationId: string;
}) => {
  const { teamId } = useAuthContext();
  const { setView, setErrorMessage, connectionId, app } = useExtensionContext();
  const integration = getIntegration(integrationId);
  const [payoutLoading, setPayoutLoading] = useState(false);
  const [reconnectNonMatching, setReconnectNonMatching] = useState(false);
  const [payoutsProgress, setPayoutsProgress] = useState<{
    total: number;
    progress: number;
    message: string;
  }>({ total: 0, progress: 0, message: '' });
  const [payoutsData, setPayoutsData] = useState<string>();

  const { displayName } = account;
  const baseProps = useBaseProps();

  const connectionDisplayName = `${
    integration?.prefix ? `${integration?.prefix} - ` : ''
  } ${displayName}`;

  const { data, isLoading: loadingExistingConnection } = useQuery(
    (q, args) => {
      const connectionById = args.connectionId
        ? q.connection({
            where: {
              id: { _eq: args.connectionId },
            },
          })
        : undefined;

      const fromAccountConnection = q.connection({
        where: {
          tenantId: { _eq: args.tenantId },
          appId: { _eq: args.appId },
          _or: [
            {
              name: { _eq: args.name },
            },
            {
              uniqueRef: { _eq: args.accountEmail?.trim().toLowerCase() },
            },
          ],
          disabled: {
            _eq: false,
          },
        },
      });

      return {
        fromAccountConnection: {
          id: fromAccountConnection?.[0]?.id as string,
          name: fromAccountConnection?.[0]?.name as string,
          uniqueRef: fromAccountConnection?.[0]?.uniqueRef as string,
        },
        givenConnection: {
          id: connectionById?.[0]?.id as string,
          uniqueRef: connectionById?.[0]?.uniqueRef as string,
          name: connectionById?.[0]?.name as string,
        },
        givenConnectionMatchesAccount:
          connectionById?.[0]?.id === fromAccountConnection?.[0]?.id,
      };
    },
    {
      skip: !teamId || !app?.id,
      queryKey: 'connections',
      variables: {
        appId: integrationId || app?.id,
        tenantId: teamId,
        name: connectionDisplayName?.trim(),
        accountEmail: account?.email || account?.displayName,
        connectionId,
      },
    }
  );

  const { mutate: addConnection, loading } = useTrpcMutation('addConnection');
  const { mutateAsync: fetchConnection } = useApiMutation(
    'post',
    '/connections/extract'
  );
  const { mutateAsync: importCsv } = useApiMutation('post', '/csv/import');

  // biome-ignore lint/correctness/useExhaustiveDependencies: <explanation>
  useEffect(() => {
    if (!connectionId || !teamId) return;

    if (!payoutsData) return;

    importCsv({
      body: {
        connectionId,
        fileData: payoutsData,
        uniqueRef: 'payout',
      },
    })
      .then(({ data }) => {
        if (data.status === 'failed') {
          setErrorMessage(data.error);
        }
      })
      .catch((error) => {
        setErrorMessage(
          error?.message ||
            'Something went wrong. Please contact support if the issue persists.'
        );
      });
  }, [payoutsData, connectionId, teamId]);

  const importPayouts = async ({
    integration,
    session,
  }: {
    integration: Integration;
    session: Session | undefined;
  }) => {
    if (!integration.payoutsUrl) return;

    await integration?.payoutsUrl?.({
      session,
      tabId,
      setPayoutsProgress,
      setPayoutsData,
    });
  };

  const submit = async (connectionId?: string, integration?: Integration) => {
    if (!integration) return;

    const session = await getSession(tabId);

    try {
      if (!teamId) throw Error('Team ID is missing');

      const result = await addConnection({
        connectionId,
        appId: integrationId || app?.id,
        name: connectionDisplayName,
        tenantId: teamId,
        params: {
          credentials: {
            ...account,
            session,
          },
        },
      });

      if (result.type === 'success') {
        if (result.id) {
          setPayoutLoading(true);
          try {
            await importPayouts({
              integration,
              session,
            });
          } catch (error) {
            console.error(error);
          } finally {
            setPayoutLoading(false);
          }

          await fetchConnection({
            body: {
              connections: [
                {
                  connectionId: result.id,
                },
              ],
            },
          });
        }

        await clearSession();

        setView('success-view');
      } else {
        throw new Error('There was an error creating the new connection.');
      }
    } catch (error: any) {
      const defaultMessage =
        'Something went wrong. Please contact support if the issue persists.';
      let message = error?.message;

      if (error instanceof ApiClientError) {
        message = getApiErrorMessage(error, defaultMessage);
      }

      setErrorMessage(message);
      setView('error-view');
    }
  };

  const fetchPayouts = async (integration: Integration) => {
    const session = await getSession(tabId);

    if (!integration.payoutsUrl) return;

    try {
      if (!teamId) throw Error('Team ID is missing');

      setPayoutLoading(true);

      await importPayouts({
        integration,
        session,
      });

      setPayoutLoading(false);

      setView('payout-success-view');
    } catch (error: any) {
      console.error(error);
      const message = error?.message;

      if (message.includes('please refresh')) {
        setErrorMessage(message);
      } else {
        setErrorMessage(
          'Unable to fetch payments from booking.com. Please contact VRP support'
        );
      }

      setView('error-view');
    }
  };

  if (integrationId !== app?.id) {
    return NotActive();
  }

  if (loadingExistingConnection)
    return <ExtensionConnectView {...baseProps} loading state="signed-in" />;

  if (payoutLoading) {
    return (
      <PayoutExtraction
        total={payoutsProgress.total}
        progress={payoutsProgress.progress}
        message={payoutsProgress.message}
      />
    );
  }

  if (reconnectNonMatching) {
    return (
      <ExtensionConnectView
        {...baseProps}
        state="reconnect-not-matching"
        loading={loading}
        primaryOnClick={
          !account?.displayName
            ? null
            : () => submit(data?.givenConnection?.id, integration)
        }
      />
    );
    // return (
    //   <>
    //     <Text component="p">
    //       Are you sure you want to reconnect this account?
    //     </Text>
    //     <Text component="p">
    //       Reconnecting will overwrite the existing connection with this account
    //       credentials.
    //     </Text>
    //     <Button
    //       variant="primary"
    //       onClick={() => submit(data?.givenConnection?.id, integration)}
    //       loading={loading}
    //       disabled={!account?.displayName}
    //     >
    //       Reconnect account
    //     </Button>
    //   </>
    // );
  }

  if (integration?.needSigning && !account?.password) {
    console.log(integration, account);
    console.log('RENDERING THIS');
    return (
      <ExtensionConnectView
        {...baseProps}
        state="not-active"
        needsRelogin
        secondaryOnClick={() => {
          window.open(app?.url, '_blank', 'noopener,noreferrer');
        }}
      />
    );
  }

  return (
    <ExtensionConnectView
      {...baseProps}
      state="signed-in"
      description={
        account?.displayName
          ? `Connected account: ${account?.displayName}`
          : 'No Account Found. Please try reloading the page.'
      }
    >
      {/* <Text component="p" mt="md" mb={20}>
            {account?.displayName ? (
              <>Connected account: {account?.displayName}</>
            ) : (
              'No Account Found. Please try reloading the page.'
            )}
          </Text> */}
      {(data?.givenConnection?.id &&
        !data.givenConnectionMatchesAccount &&
        (data.fromAccountConnection.name ? (
          <Text component="p" mb={20} mt="md" ta="center">
            You cannot reconnect this connection ({data.givenConnection.name})
            as it is already linked to another connection (
            {data.fromAccountConnection.name}).
          </Text>
        ) : (
          <>
            <Text component="p" mb={20} ta="center">
              You cannot reconnect this account as it is not matching (
              {data.givenConnection.uniqueRef}).
            </Text>
            <Button
              onClick={() => setReconnectNonMatching(true)}
              variant="primary"
              loading={loading}
              disabled={!account?.displayName}
            >
              Reconnect anyways
            </Button>
          </>
        ))) ||
        (data?.fromAccountConnection?.id && (
          <>
            <Text component="p" ta="center" my="md">
              You already have a connection for this account.
            </Text>
            <Button
              variant="primary"
              onClick={() =>
                submit(data?.fromAccountConnection?.id, integration)
              }
              loading={loading || payoutLoading}
              disabled={!account?.displayName}
            >
              Reconnect account
            </Button>

            <Button
              variant="primary"
              style={{ marginTop: rem(10) }}
              onClick={() => submit(undefined, integration)}
              loading={loading || payoutLoading}
              disabled={!account?.displayName}
            >
              Add connection
            </Button>

            {integration?.payoutsUrl &&
              integration?.prefix === 'booking.com' && (
                <Button
                  style={{ marginTop: rem(10) }}
                  variant="primary"
                  onClick={() => fetchPayouts(integration)}
                  loading={payoutLoading}
                  disabled={!account?.displayName}
                >
                  Fetch payouts
                </Button>
              )}
          </>
        )) || (
          <Button
            sx={(theme) => ({
              marginTop: theme.spacing.md,
            })}
            variant="primary"
            onClick={() => submit(data?.givenConnection?.id, integration)}
            loading={loading || payoutLoading}
            disabled={!account?.displayName}
          >
            {connectionId ? 'Reconnect account' : 'Add connection'}
          </Button>
        )}
    </ExtensionConnectView>
  );
};
