import { Button } from '@finalytic/components';
import { Icon, type IconDefinition } from '@finalytic/icons';
import { LoadingIndicator } from '@finalytic/ui';
import { Center, Stack, Text, useMantineTheme } from '@mantine/core';
import type { PropsWithChildren, ReactNode } from 'react';
import {
  ExtensionAppIcon,
  type ExtensionAppIconProps,
  ExtensionViewHeader,
} from '../components';

type ExtensionConnectViewProps = {
  children?: ReactNode;
  loading: boolean;
  needsRelogin?: boolean;
  description?: string;
  app: ExtensionAppIconProps['app'];
  state: ExtensionAppIconProps['state'];
} & WrapperProps & {
    secondaryOnClick?: null | (() => void);
    primaryOnClick?: null | (() => void);
  };

export const ExtensionConnectView = (props: ExtensionConnectViewProps) => {
  const { onReturn, app, loading, state, needsRelogin } = props;

  if (loading || state === 'signing-in')
    return (
      <Wrapper {...props}>
        <LoadingIndicator size="sm" />
      </Wrapper>
    );

  if (!app)
    return (
      <Wrapper {...props}>
        <Icon
          icon="AlertTriangleIcon"
          color={(theme) => theme.colors.orange[6]}
        />
        <Text ta="center" fw={500} mt="md" mb="sm" size="md">
          We failed to load the app
        </Text>

        <Text ta="center" c="neutral" size="xs" mb="lg" mx="auto" maw={400}>
          We have captured the error and will look into it. Please return to the
          overview and retry in the meantime.
        </Text>
        <Button onClick={onReturn} size="xs" leftIcon="ArrowLeftIcon">
          Return to overview
        </Button>
      </Wrapper>
    );

  console.log(state);

  if (state === 'not-active') {
    return (
      <Wrapper {...props}>
        <Action
          app={app}
          state={state}
          title={
            needsRelogin
              ? `Sign out of ${app.name} to connect`
              : `Complete Connection to ${app.name}`
          }
          description={
            needsRelogin ? (
              <>Please log out and sign in again on {app?.name}.</>
            ) : (
              <>
                To finish setting up,
                <br />
                sign in to your {app.name} account.
              </>
            )
          }
          secondary={{
            label: `Open ${app.name}`,
            onClick: props.secondaryOnClick,
            icon: 'ExternalLinkIcon',
          }}
        />
      </Wrapper>
    );
  }

  if (state === 'reconnect-not-matching') {
    return (
      <Wrapper {...props}>
        <Action
          app={app}
          state={state}
          title={'Are you sure you want to reconnect this account?'}
          description={
            'Reconnecting will overwrite the existing connection with this account credentials.'
          }
          primary={{
            label: 'Reconnect account',
            onClick: props.primaryOnClick,
            icon: 'ArrowCornerCcwRbIcon',
          }}
        />
      </Wrapper>
    );
  }

  return (
    <Wrapper {...props}>
      <Action app={app} state={state} description={props.description}>
        {props.children}
      </Action>
    </Wrapper>
  );
};

type WrapperProps = {
  header: string;
  onReturn: () => void;
};

const Wrapper = ({
  children,
  header,
  onReturn,
}: PropsWithChildren<WrapperProps>) => {
  return (
    <>
      <ExtensionViewHeader title={header} onReturn={onReturn} />
      <Center
        sx={{
          height: '100%',
          flexDirection: 'column',
          flex: '1',
        }}
      >
        {children}
      </Center>
    </>
  );
};

type ActionProps = {
  title?: ReactNode;
  description: ReactNode;
  primary?: {
    onClick?: null | (() => void);
    label: string;
    icon?: IconDefinition;
  };
  secondary?: {
    onClick?: null | (() => void);
    label: string;
    icon?: IconDefinition;
  };
};

export const Action = ({
  description,
  title,
  app,
  secondary,
  primary,
  state,
  children,
}: ActionProps & {
  app: NonNullable<ExtensionConnectViewProps['app']>;
  state: ExtensionConnectViewProps['state'];
  children?: ReactNode;
}) => {
  const theme = useMantineTheme();

  return (
    <>
      <Center mb="xl">
        <ExtensionAppIcon app={app} state={state} />
      </Center>
      {title &&
        (typeof title !== 'string' ? (
          title
        ) : (
          <Text
            ta="center"
            fw={600}
            mb="sm"
            size="md"
            c={theme.colors.neutral[8]}
          >
            {title}
          </Text>
        ))}
      <Text
        ta="center"
        c={theme.colors.neutral[8]}
        size="xs"
        mb="xl"
        mx="auto"
        maw={400}
      >
        {description}
      </Text>
      {children || (
        <Stack>
          {primary?.onClick !== undefined && (
            <Button
              onClick={primary.onClick ?? undefined}
              disabled={primary.onClick === null}
              variant="primary"
              leftIcon={primary.icon}
            >
              {primary.label}
            </Button>
          )}
          {secondary?.onClick !== undefined && (
            <Button
              onClick={secondary.onClick ?? undefined}
              disabled={secondary.onClick === null}
              leftIcon={secondary.icon}
            >
              {secondary.label}
            </Button>
          )}
        </Stack>
      )}
    </>
  );
};
