import { useQuery } from '@finalytic/data';
import {
  type ReactNode,
  createContext,
  useContext,
  useMemo,
  useState,
} from 'react';
import { useEffect } from 'react';

function useApp({
  appId,
  connectionId,
}: {
  appId: string | undefined;
  connectionId: string | undefined;
}) {
  const { data: app, isLoading: loading } = useQuery(
    (q, args) => {
      const apps = q
        .app({
          where: {
            id: args.appId ? { _eq: args.appId } : undefined,
            connections: args.connectionId
              ? { id: { _eq: args.connectionId } }
              : undefined,
          },
          limit: 1,
        })
        .map((app) => ({
          id: app.id as string,
          name: app.name as string,
          icon: app.iconRound,
          url: app.authentication({ path: 'extension.url' }) || '',
        }));

      return apps[0];
    },
    {
      variables: {
        appId,
        connectionId,
      },
      skip: !appId && !connectionId,
    }
  );

  return {
    app,
    loading,
  };
}

export type View =
  | 'list-view'
  | 'add-view'
  | 'connect-view'
  | 'success-view'
  | 'payout-success-view'
  | 'error-view';

// Keys for extensions localStorage => don't collide with useAuthContext
const localStorageViewKey = 'view';
const localStorageAppKey = 'appId';
const localStorageConnectionKey = 'connectionId';

type context = {
  view: View;
  setView: (view: View) => void;
  resetView: () => void;

  errorMessage?: string;
  setErrorMessage: (msg?: string) => void;

  appId: string | undefined;
  setAppId: (appId: string) => void;

  app: ReturnType<typeof useApp>['app'];
  appLoading: boolean;

  connectionId: string | undefined;
  setConnectionId: (connectionId: string) => void;
};

const ExtensionViewContext = createContext<context | null>(null);

export type ExtensionContextProviderProps = {
  children?: ReactNode;
};

export const useExtensionContext = () =>
  useContext(ExtensionViewContext) as context;

export const ExtensionContextProvider = ({
  children,
}: ExtensionContextProviderProps) => {
  const [view, setView] = useState<View>('list-view');
  const [appId, setAppId] = useState<string>();
  const [connectionId, setConnectionId] = useState<string>();
  const [errorMessage, setErrorMessage] = useState<string | undefined>();

  const { app, loading: appLoading } = useApp({ appId, connectionId });

  const updateView = (nextView: View) => {
    chrome.storage.local.set({
      [localStorageViewKey]: nextView,
    });
  };

  const updateAppId = (nextAppId: string | undefined) => {
    chrome.storage.local.set({
      [localStorageAppKey]: nextAppId,
      [localStorageConnectionKey]: '',
    });
  };

  const updateConnectionId = (nextConnectionId: string | undefined) => {
    chrome.storage.local.set({
      [localStorageConnectionKey]: nextConnectionId,
      [localStorageAppKey]: '',
    });
  };

  const resetView = () => {
    setErrorMessage(undefined);
    chrome.storage.local.set({
      [localStorageViewKey]: 'list-view',
      [localStorageConnectionKey]: '',
      [localStorageAppKey]: '',
    });
  };

  // Listen to values from localStorage
  useEffect(() => {
    const listener = (changes: {
      [key: string]: chrome.storage.StorageChange;
    }) => {
      if (localStorageAppKey in changes)
        setAppId(changes[localStorageAppKey].newValue);
      if (localStorageViewKey in changes)
        setView(changes[localStorageViewKey].newValue);
      if (localStorageConnectionKey in changes)
        setConnectionId(changes[localStorageConnectionKey].newValue);
    };
    chrome.storage.onChanged.addListener(listener);
    chrome.storage.local.get().then((state) => {
      console.log(state);

      listener({
        [localStorageAppKey]: { newValue: state[localStorageAppKey] },
        [localStorageConnectionKey]: {
          newValue: state[localStorageConnectionKey],
        },
        [localStorageViewKey]: { newValue: state[localStorageViewKey] },
      });
    });

    return () => chrome.storage.onChanged.removeListener(listener);
  }, []);

  const value = useMemo(
    () => ({
      view,
      setView: updateView,
      resetView,
      errorMessage,
      setErrorMessage,
      appId,
      setAppId: updateAppId,
      connectionId,
      setConnectionId: updateConnectionId,
      app,
      appLoading,
    }),
    [
      view,
      errorMessage,
      appId,
      connectionId,
      app,
      appLoading,
      updateView,
      updateAppId,
      updateConnectionId,
      resetView,
    ]
  );

  return (
    <ExtensionViewContext.Provider value={value}>
      {children}
    </ExtensionViewContext.Provider>
  );
};
